import './styles.css'

type AppId = 'sobre' | 'projetos' | 'habilidades' | 'curriculo' | 'contato' | 'terminal' | 'studio' | 'arquivos'
const apps = [
  { id: 'sobre' as AppId, label: 'Sobre mim', subtitle: 'perfil.txt', color: '#a99cff', icon: UserRound },
  { id: 'projetos' as AppId, label: 'Meus Projetos', subtitle: 'projetos.app', color: '#77d8be', icon: FolderKanban },
  { id: 'habilidades' as AppId, label: 'Habilidades', subtitle: 'stack.dev', color: '#f6bd76', icon: Sparkles },
  { id: 'curriculo' as AppId, label: 'Currículo', subtitle: 'henrique.pdf', color: '#82b8ff', icon: FileText },
  { id: 'contato' as AppId, label: 'Contato', subtitle: 'mensagens', color: '#ef91b3', icon: Mail },
  { id: 'terminal' as AppId, label: 'Terminal', subtitle: 'bash', color: '#9c8cff', icon: Terminal },
  { id: 'studio' as AppId, label: 'Henrique Studio', subtitle: 'app autoral', color: '#6fe0ca', icon: Palette },
  { id: 'arquivos' as AppId, label: 'Arquivos', subtitle: 'projetos/', color: '#e5a96b', icon: FolderKanban },
]
const groups = { Frontend: ['HTML', 'CSS', 'JavaScript', 'TypeScript', 'Vue', 'Ionic', 'React'], Backend: ['PHP', 'MySQL'], Mobile: ['Capacitor', 'SQLite'], Outros: ['Bluetooth Low Energy', 'Git', 'GitHub', 'Figma', 'QR Code', 'IoT'] }
const openApps = ref<AppId[]>(['sobre']); const focused = ref<AppId>('sobre'); const selectedProject = ref<Project | null>(null); const now = ref(new Date()); const terminalInput = ref(''); const terminalLines = ref(['HenriqueOS Terminal v1.0', 'Digite "help" para ver os comandos disponíveis.', '']); let timer: number
onMounted(() => { timer = window.setInterval(() => now.value = new Date(), 1000) }); onUnmounted(() => window.clearInterval(timer))
const open = (id: AppId) => { if (!openApps.value.includes(id)) openApps.value.push(id); focused.value = id }
const close = (id: AppId) => { openApps.value = openApps.value.filter(app => app !== id); if (focused.value === id) focused.value = openApps.value.at(-1) || 'studio' }
const toggle = (id: AppId) => openApps.value.includes(id) ? focused.value = id : open(id)
const clock = computed(() => now.value.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })); const date = computed(() => now.value.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: 'short' }).replace('.', ''))
const appInfo = (id: AppId) => apps.find(app => app.id === id)!
const openLink = (url: string) => { window.open(url, '_blank', 'noopener,noreferrer') }
const openEmail = () => { window.location.href = 'mailto:henrique16.schenkel@gmail.com' }
const runCommand = () => { const command = terminalInput.value.trim().toLowerCase(); if (!command) return; if (command === 'clear') terminalLines.value = []; else { const output: Record<string, string[]> = { help: ['comandos disponíveis:', '  help             mostra esta lista', '  whoami           mostra meu perfil', '  cat curriculo.txt  mostra o currículo', '  date             mostra data e hora', '  clear            limpa o terminal', '  open curriculo   abre a janela currículo'], whoami: ['Henrique — estudante de Informática pelo Senac Joinville.', 'Foco: desenvolvimento e soluções tecnológicas.'], 'cat curriculo.txt': ['Henrique Schenkel Araujo', 'Estudante de Informática pelo Senac Joinville.', 'Buscando primeira oportunidade na área de tecnologia.'], date: [now.value.toLocaleString('pt-BR')], 'open curriculo': ['Abrindo currículo...'] }; terminalLines.value.push(`henrique@portfolio:~$ ${command}`, ...(output[command] || [`comando não encontrado: ${command}`, 'Digite "help" para ver as opções.'])); if (command === 'open curriculo') open('curriculo') } terminalInput.value = '' }
const printResume = () => window.print()
</script>

