    <div class="desktop-icons"><button v-for="app in apps" :key="app.id" class="desktop-icon" :class="{ selected: focused === app.id }" @click="focused = app.id" @dblclick="open(app.id)"><span class="app-icon" :style="{ color: app.color, '--icon-color': app.color }"><component :is="app.icon" /></span><b>{{ app.label }}</b><small>{{ app.subtitle }}</small></button></div>
